for i,definition,reason,parts in [
(23,'热电压与混合电化学总输出','0/1/2/3/4/6/8/9均由热刺激产生的热电压，9摘要排除交变压电信号；5的0.71V只有约33%热贡献，不能等同纯热电压；7为热充电赝电容和红氧复合单元输出，独立保留。',[('热驱动输出电压',[0,1,2,3,4,6,8,9]),('热与化学势复合总电压',[5]),('热充电电池复合电压',[7])]),
(26,'热电压及高值和局部内电势','0/1/2/4/5/6/8/9均离子热驱动装置电压，界面/体相贡献是成因；3明确高值，7为p-n结内部电势差不能直接当端输出。',[('离子热电压',[0,1,2,4,5,6,8,9]),('高热电压',[3]),('p-n结内部电势差',[7])]),
(28,'p型导电与材料或保持条件','0/1/2/3/4/5/8均电子空穴占优p型特征；6明确Cs2CdZnCl6材料限制；7要求全测温区保持p型，不能去掉稳定区间。',[('p型电子导电特征',[0,1,2,3,4,5,8]),('Cs2CdZnCl6的p型特征',[6]),('测量温区持续p型',[7])]),
(29,'红氧熵差及特定电对','1/2/3/6经完整摘要核实均铁氰/亚铁氰红氧系统熵差；0具体Cu-乙二胺螯合反应；4/5/7一般红氧反应熵差，不通过泛称把特定反应合并。',[('Cu-乙二胺电化学反应熵差',[0]),('铁氰/亚铁氰红氧熵差',[1,2,3,6]),('红氧反应熵差',[4,5,7])]),
(30,'电阻率与高值和增加','0/3/5/7为电阻率量；1/2为相对基准较高状态；4/6明确增加变化，不混合物理量和状态事件。',[('电阻率',[0,3,5,7]),('较高电阻率',[1,2]),('电阻率增加',[4,6])]),
(31,'迁移率差、迁移速率差与扩散速率差','1/2/3/6为阴阳离子迁移率不对称；0/5为热迁移速率差；4为扩散速率差；7进一步限定Li+/Cl-。速度或扩散率不能仅凭关联当迁移率。',[('阴阳离子迁移率差',[1,2,3,6]),('阴阳离子热迁移速率差',[0,5]),('阴阳离子扩散速率差',[4]),('Li+/Cl-扩散速率差',[7])]),
(32,'低热导率的材料和程度','0/1均Cu7PSe6低热导率，2原文明确ultra-low而非通常low；3/4/5/6/7仅一般低热导率状态，严格不消去材料限定及超低程度。',[('Cu7PSe6低热导率',[0,1]),('超低热导率',[2]),('低热导率',[3,4,5,6,7])]),
(33,'混合离子共价键合','1/2/3/4/5/6/7均键合同时含离子/共价特性的一般类别；0明确Ge-O键限定，不与所有混合键合无条件合并。',[('Ge-O混合离子共价键合',[0]),('混合离子共价键合',[1,2,3,4,5,6,7])]),
(34,'输出功率及归一化量','0/4/5/7为W/m²面积功率，4虽名output power但单位纠正其量纲；1/2/6为再除温差平方的功率密度；3为总输出功率。不能跨量纲合并。',[('面积输出功率密度',[0,4,5,7]),('温差平方归一化面积功率密度',[1,2,6]),('输出功率',[3])]),
(35,'真实温度梯度与温差记号','1/4为以K给出的DeltaT，2/5原文虽称gradient但用温度差单位描述宏观两端差；0/3/6为空间温度梯度未给相同DeltaT定义，不把二者混合。',[('空间温度梯度',[0,3,6]),('两端温度差',[1,2,4,5])]),
(38,'离子热电极性与电子导电类型转换','0/1为离子热电负到正极性；2/4/5/6为电子n到p转换；3仅载流子符号反转且无固定方向，不能删除起止条件。',[('离子热电n到p转换',[0,1]),('电子n到p转换',[2,4,5,6]),('载流子符号反转未限定方向',[3])]),
(39,'离子电导率与优越离子电导率','0/1/2/3/5都离子电导率量，5 ionic electrical为同量展开；4明确相对其他溶剂系统优越，属于比较状态。',[('离子电导率',[0,1,2,3,5]),('优越离子电导率',[4])])]:record(i,'split',definition,reason,[{'definition':d,'members':m} for d,m in parts])
